<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeAttributes;
use Civi\Lughauth\Features\Document\Theme\Domain\Theme;

final class ThemeUnitTest extends TestCase
{
  public function test_init_store_values(): void
  {
    // @Arrange
    $one = new Theme(
      uid: 'one',
      tenant: new TenantRef('one'),
      name: 'one',
      isDefault: true,
      enabled: true,
      customCss: 'one',
      version: 1,
    );

    // @Act
    $other = $one->toAttributes()->build();
    $calculated = Theme::calculatedFields();

    // @Assert
    $this->assertEquals([], $calculated);
    $this->assertEquals( $one->uid(), $other->uid());
    $this->assertEquals( $one->getTenant(), $other->getTenant());
    $this->assertTrue( $one->isTenantChanged() );
    $this->assertEquals( $one->getName(), $other->getName());
    $this->assertTrue( $one->isNameChanged() );
    $this->assertEquals( $one->isIsDefault(), $other->isIsDefault());
    $this->assertTrue( $one->isIsDefaultChanged() );
    $this->assertEquals( $one->isEnabled(), $other->isEnabled());
    $this->assertTrue( $one->isEnabledChanged() );
    $this->assertEquals( $one->getCustomCss(), $other->getCustomCss());
    $this->assertTrue( $one->isCustomCssChanged() );
    $this->assertEquals( $one->getVersion(), $other->getVersion());
    $this->assertTrue( $one->isVersionChanged() );
  }
  public function test_replace_change_values(): void
  {
    // @Arrange
    $base = new Theme(
      uid: 'one',
      tenant: new TenantRef('one'),
      name: 'one',
      isDefault: true,
      enabled: true,
      customCss: 'one',
      version: 1,
    );
    $other = new Theme(
      uid: 'other',
      tenant: new TenantRef('other'),
      name: 'other',
      isDefault: false,
      enabled: false,
      customCss: 'other',
      version: 2,
    );

    // @Act
    $one = $base->replace( $other->toAttributes() );

    // @Assert
    $this->assertEquals( $one->uid(), $base->uid());
    $this->assertEquals( $one->getTenant(), $other->getTenant());
    $this->assertTrue( $one->isTenantChanged($base) );
    $this->assertEquals( $one->getName(), $other->getName());
    $this->assertTrue( $one->isNameChanged($base) );
    $this->assertEquals( $one->isIsDefault(), $other->isIsDefault());
    $this->assertTrue( $one->isIsDefaultChanged($base) );
    $this->assertEquals( $one->isEnabled(), $other->isEnabled());
    $this->assertTrue( $one->isEnabledChanged($base) );
    $this->assertEquals( $one->getCustomCss(), $other->getCustomCss());
    $this->assertTrue( $one->isCustomCssChanged($base) );
    $this->assertEquals( $one->getVersion(), $other->getVersion());
    $this->assertTrue( $one->isVersionChanged($base) );
  }
  public function test_json_compare(): void
  {
    // @Arrange
    $one = new Theme(
      uid: 'one',
      tenant: new TenantRef('one'),
      name: 'one',
      isDefault: true,
      enabled: true,
      customCss: 'one',
      version: 1,
    );

    // @Act
    $json = $one->asPublicJson();

    // @Assert
$this->assertEquals('one', $json['uid']);
$this->assertEquals('one', $json['tenant']['$ref'] );
$this->assertEquals('one', $json['name']);
$this->assertEquals(true, $json['isDefault']);
$this->assertEquals(true, $json['enabled']);
$this->assertEquals('one', $json['customCss']);
$this->assertEquals(1, $json['version']);
  }
  public function test_create_store_values(): void
  {
    // @Arrange
    $one = new Theme(
      uid: 'one',
      tenant: new TenantRef('one'),
      name: 'one',
      isDefault: true,
      enabled: true,
      customCss: 'one',
      version: 1,
    );

    // @Act
    $other = Theme::create($one->toAttributes() );

    // @Assert
    $this->assertEquals( $one->uid(), $other->uid());
    $this->assertEquals( $one->getTenant(), $other->getTenant());
    $this->assertTrue( $one->isTenantChanged() );
    $this->assertEquals( $one->getName(), $other->getName());
    $this->assertTrue( $one->isNameChanged() );
    $this->assertEquals( $one->isIsDefault(), $other->isIsDefault());
    $this->assertTrue( $one->isIsDefaultChanged() );
    $this->assertEquals( $one->isEnabled(), $other->isEnabled());
    $this->assertTrue( $one->isEnabledChanged() );
    $this->assertEquals( $one->getCustomCss(), $other->getCustomCss());
    $this->assertTrue( $one->isCustomCssChanged() );
    $this->assertEquals( $one->getVersion(), $other->getVersion());
    $this->assertTrue( $one->isVersionChanged() );
    $this->assertCount(0, $one->getTheEvents() );
    $this->assertCount(1, $other->getTheEvents() );
  }
  public function test_update_change_values(): void
  {
    $base = new Theme(
      uid: 'one',
      tenant: new TenantRef('one'),
      name: 'one',
      isDefault: true,
      enabled: true,
      customCss: 'one',
      version: 1,
    );
    $other = new Theme(
      uid: 'other',
      tenant: new TenantRef('other'),
      name: 'other',
      isDefault: false,
      enabled: false,
      customCss: 'other',
      version: 2,
    );

    // @Act
    $one = $base->update( $other->toAttributes() );

    // @Assert
    $this->assertEquals( $one->uid(), $base->uid());
    $this->assertEquals( $one->getTenant(), $other->getTenant());
    $this->assertTrue( $one->isTenantChanged($base) );
    $this->assertEquals( $one->getName(), $other->getName());
    $this->assertTrue( $one->isNameChanged($base) );
    $this->assertEquals( $one->isIsDefault(), $other->isIsDefault());
    $this->assertTrue( $one->isIsDefaultChanged($base) );
    $this->assertEquals( $one->isEnabled(), $other->isEnabled());
    $this->assertTrue( $one->isEnabledChanged($base) );
    $this->assertEquals( $one->getCustomCss(), $other->getCustomCss());
    $this->assertTrue( $one->isCustomCssChanged($base) );
    $this->assertEquals( $one->getVersion(), $other->getVersion());
    $this->assertTrue( $one->isVersionChanged($base) );
    $this->assertCount(0, $other->getTheEvents() );
    $this->assertCount(1, $one->getTheEvents() );
  }
